tool_schemas.implementation:
def list_calls(workspace_id, status=None, source=None, started_at_gte=None, started_at_lte=None, ended_at_gte=None, ended_at_lte=None, gong_call_id=None, limit=None, cursor=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, time, re, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0437000" if __import__("os").path.isdir("./environment_mix/0437000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(ss)
        except ValueError:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _today0_utc(dt):
        d = dt.astimezone(datetime.timezone.utc).date()
        return datetime.datetime(d.year, d.month, d.day, 0, 0, 0, tzinfo=datetime.timezone.utc)

    def _log(api_key_id, status_s, error_code=None, error_message=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + base64.urlsafe_b64encode(os.urandom(12)).decode("ascii").rstrip("="),
            "endpoint": "list_calls",
            "api_key_id": api_key_id,
            "status": status_s,
            "error_code": error_code,
            "error_message": error_message,
            "meta": meta or {},
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _iso(now),
        })
        _save("request_logs.json", logs)

    def _choose_ambient_key_for_workspace(ws_id):
        wss = _load("workspaces.json")
        ws = next((w for w in wss if w.get("id") == ws_id), None)
        if not ws:
            return None, None, _err("NOT_FOUND", "Workspace not found")
        if ws.get("status") != "active":
            return None, ws, _err("UNAUTHORIZED", "Workspace is not active")
        keys = _load("api_keys.json")
        candidates = [k for k in keys if k.get("workspace_id") == ws_id and k.get("status") == "active"]
        if not candidates:
            return None, ws, _err("UNAUTHORIZED", "No active API key available for this workspace")
        # pick a key that is under quota today (after rollover) if possible
        today0 = _today0_utc(now)
        usable = []
        for k in candidates:
            dcd = _parse_dt(k.get("daily_count_date"))
            cnt = k.get("daily_call_count")
            lim = k.get("daily_call_limit")
            try:
                cnt = int(cnt)
                lim = int(lim)
            except Exception:
                continue
            if lim < 0 or cnt < 0:
                continue
            eff_cnt = cnt if dcd == today0 else 0
            if eff_cnt <= lim:
                usable.append((lim - eff_cnt, k))
        if not usable:
            # still return a candidate for logging, but auth fails on quota rules
            return candidates[0], ws, _err("QUOTA_EXCEEDED", "Daily call limit exceeded")
        usable.sort(key=lambda x: x[0], reverse=True)
        return usable[0][1], ws, None

    def _enforce_and_increment_quota(api_key_row):
        if not api_key_row:
            return _err("UNAUTHORIZED", "No API key context")
        keys = _load("api_keys.json")
        today0 = _today0_utc(now)
        for k in keys:
            if k.get("id") == api_key_row.get("id"):
                dcd = _parse_dt(k.get("daily_count_date"))
                if dcd != today0:
                    k["daily_call_count"] = 0
                    k["daily_count_date"] = _iso(today0)
                try:
                    cnt = int(k.get("daily_call_count", 0))
                    lim = int(k.get("daily_call_limit", 0))
                except Exception:
                    return _err("VALIDATION_ERROR", "API key quota fields are invalid")
                if cnt + 1 > lim:
                    return _err("QUOTA_EXCEEDED", "Daily call limit exceeded", daily_call_limit=lim, daily_call_count=cnt)
                k["daily_call_count"] = cnt + 1
                k["last_used_at"] = _iso(now)
                k["updated_at"] = _iso(now)
                _save("api_keys.json", keys)
                return None
        return _err("UNAUTHORIZED", "API key not found")

    # Validate inputs (relax: allow higher limit by clamping; cursor opaque; don't error on huge limit)
    if not isinstance(workspace_id, str) or not re.match(r"^gong_ws_[0-9A-Z]{18,}$", workspace_id):
        _log(None, "error", "VALIDATION_ERROR", "workspace_id is invalid")
        return _err("VALIDATION_ERROR", "workspace_id is invalid")

    allowed_status = {"imported", "processing_transcript", "ready", "failed", "deleted"}
    if status is not None:
        if not isinstance(status, list) or any((not isinstance(s, str) or s not in allowed_status) for s in status):
            _log(None, "error", "VALIDATION_ERROR", "status must be an array of valid statuses")
            return _err("VALIDATION_ERROR", "status must be an array of valid statuses")

    if source is not None and source != "gong":
        _log(None, "error", "VALIDATION_ERROR", "source must be 'gong'")
        return _err("VALIDATION_ERROR", "source must be 'gong'")

    dt_started_gte = _parse_dt(started_at_gte)
    if started_at_gte is not None and dt_started_gte is None:
        _log(None, "error", "VALIDATION_ERROR", "started_at_gte must be RFC3339 date-time")
        return _err("VALIDATION_ERROR", "started_at_gte must be RFC3339 date-time")
    dt_started_lte = _parse_dt(started_at_lte)
    if started_at_lte is not None and dt_started_lte is None:
        _log(None, "error", "VALIDATION_ERROR", "started_at_lte must be RFC3339 date-time")
        return _err("VALIDATION_ERROR", "started_at_lte must be RFC3339 date-time")
    dt_ended_gte = _parse_dt(ended_at_gte)
    if ended_at_gte is not None and dt_ended_gte is None:
        _log(None, "error", "VALIDATION_ERROR", "ended_at_gte must be RFC3339 date-time")
        return _err("VALIDATION_ERROR", "ended_at_gte must be RFC3339 date-time")
    dt_ended_lte = _parse_dt(ended_at_lte)
    if ended_at_lte is not None and dt_ended_lte is None:
        _log(None, "error", "VALIDATION_ERROR", "ended_at_lte must be RFC3339 date-time")
        return _err("VALIDATION_ERROR", "ended_at_lte must be RFC3339 date-time")

    if gong_call_id is not None and (not isinstance(gong_call_id, str) or not gong_call_id.strip()):
        _log(None, "error", "VALIDATION_ERROR", "gong_call_id must be a non-empty string")
        return _err("VALIDATION_ERROR", "gong_call_id must be a non-empty string")

    if limit is None:
        limit = 100
    if not isinstance(limit, int):
        _log(None, "error", "VALIDATION_ERROR", "limit must be an integer")
        return _err("VALIDATION_ERROR", "limit must be an integer")
    if limit < 1:
        _log(None, "error", "VALIDATION_ERROR", "limit must be >= 1")
        return _err("VALIDATION_ERROR", "limit must be >= 1")
    # Relax vendor max: clamp rather than reject
    if limit > 200:
        limit = 200

    if sort_by is None:
        sort_by = "started_at"
    if sort_by not in {"started_at", "ended_at", "created_at", "updated_at"}:
        _log(None, "error", "VALIDATION_ERROR", "sort_by is invalid")
        return _err("VALIDATION_ERROR", "sort_by is invalid")

    if sort_order is None:
        sort_order = "desc"
    if sort_order not in {"asc", "desc"}:
        _log(None, "error", "VALIDATION_ERROR", "sort_order is invalid")
        return _err("VALIDATION_ERROR", "sort_order is invalid")

    # Ambient auth context for reads that require tenancy; enforce quota on success
    api_key_row, ws_row, auth_err = _choose_ambient_key_for_workspace(workspace_id)
    if auth_err:
        _log(api_key_row.get("id") if isinstance(api_key_row, dict) else None, "error", auth_err["error"]["code"], auth_err["error"]["message"], {"workspace_id": workspace_id})
        return auth_err

    calls = _load("calls.json")
    if not isinstance(calls, list):
        calls = []

    # Filter by workspace and non-deleted (business rule)
    out = []
    for c in calls:
        if c.get("workspace_id") != workspace_id:
            continue
        if c.get("status") == "deleted":
            continue
        if status is not None and c.get("status") not in set(status):
            continue
        if source is not None and c.get("source") != source:
            continue
        if gong_call_id is not None and str(c.get("gong_call_id")) != gong_call_id:
            continue
        c_started = _parse_dt(c.get("started_at"))
        c_ended = _parse_dt(c.get("ended_at"))
        if dt_started_gte is not None:
            if c_started is None or c_started < dt_started_gte:
                continue
        if dt_started_lte is not None:
            if c_started is None or c_started > dt_started_lte:
                continue
        if dt_ended_gte is not None:
            if c_ended is None or c_ended < dt_ended_gte:
                continue
        if dt_ended_lte is not None:
            if c_ended is None or c_ended > dt_ended_lte:
                continue
        out.append(c)

    # Sort: None values last for asc, first for desc (stable)
    def _sort_key(row):
        v = row.get(sort_by)
        dt = _parse_dt(v)
        if dt is None:
            # use extreme sentinel; we also add row id tie-breaker
            if sort_order == "asc":
                return (1, datetime.datetime.max.replace(tzinfo=datetime.timezone.utc), row.get("id", ""))
            return (0, datetime.datetime.min.replace(tzinfo=datetime.timezone.utc), row.get("id", ""))
        return (0, dt, row.get("id", ""))

    reverse = (sort_order == "desc")
    out.sort(key=_sort_key, reverse=reverse)

    # Cursor is opaque; implement as "after_id:<id>" if we produced it, else ignore unknown cursors safely
    start_idx = 0
    if cursor is not None:
        if isinstance(cursor, str) and cursor.startswith("after_id:"):
            after_id = cursor.split("after_id:", 1)[1]
            for i, row in enumerate(out):
                if row.get("id") == after_id:
                    start_idx = i + 1
                    break
        else:
            # unknown cursor: treat as empty page start (don't error)
            start_idx = 0

    page = out[start_idx:start_idx + limit]
    has_more = (start_idx + limit) < len(out)
    next_cursor = ("after_id:" + page[-1].get("id")) if (has_more and page and page[-1].get("id")) else None

    quota_err = _enforce_and_increment_quota(api_key_row)
    if quota_err:
        _log(api_key_row.get("id"), "error", quota_err["error"]["code"], quota_err["error"]["message"], {"workspace_id": workspace_id})
        return quota_err

    _log(api_key_row.get("id"), "success", meta={"workspace_id": workspace_id, "returned": len(page), "total": len(out)})
    return {
        "calls": page,
        "meta": {
            "total": len(out),
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort_by": sort_by,
            "sort_order": sort_order,
        }
    }

def retrieve_transcripts(workspace_id, call_ids, include_sentences=None, include_topics=None, include_speaker_index=None, sentences_limit=None, sentences_cursor=None, sentence_start_ms_gte=None, sentence_end_ms_lte=None, speaker_id=None, **_extra):
    import json, os, datetime, time, re, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0437000" if __import__("os").path.isdir("./environment_mix/0437000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str): return dt
        if dt.tzinfo is None: dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _today0_utc(dt):
        d = dt.astimezone(datetime.timezone.utc).date()
        return datetime.datetime(d.year, d.month, d.day, 0, 0, 0, tzinfo=datetime.timezone.utc)

    def _gen_req_id():
        return "req_" + base64.urlsafe_b64encode(os.urandom(12)).decode("ascii").rstrip("=")

    def _log(api_key_id, status_s, error_code=None, error_message=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": _gen_req_id(),
            "endpoint": "retrieve_transcripts",
            "api_key_id": api_key_id,
            "status": status_s,
            "error_code": error_code,
            "error_message": error_message,
            "meta": meta or {},
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _iso(now),
        })
        _save("request_logs.json", logs)

    def _rate_and_select_key(target_workspace_id):
        # Ambient auth: pick any active key for this workspace, enforce daily quota.
        keys = _load("api_keys.json")
        if not isinstance(keys, list): keys = []
        today0 = _today0_utc(now)
        today0_iso = _iso(today0)
        chosen = None
        for k in keys:
            if not isinstance(k, dict): 
                continue
            if k.get("workspace_id") != target_workspace_id:
                continue
            if k.get("status") != "active":
                continue
            # reset daily counter if rolled over
            k_date = k.get("daily_count_date")
            if not isinstance(k_date, str) or k_date != today0_iso:
                k["daily_call_count"] = 0
                k["daily_count_date"] = today0_iso
                k["updated_at"] = _iso(now)
            limit = k.get("daily_call_limit")
            count = k.get("daily_call_count")
            if not isinstance(limit, int) or limit < 0:
                continue
            if not isinstance(count, int) or count < 0:
                k["daily_call_count"] = 0
                count = 0
            if count + 1 <= limit:
                chosen = k
                break
        if chosen is None:
            return None, None, _err("UNAUTHORIZED", "No active API key available for this workspace")
        # enforce quota
        if chosen["daily_call_count"] + 1 > chosen["daily_call_limit"]:
            return None, keys, _err("QUOTA_EXCEEDED", "Daily call limit exceeded", api_key_id=chosen.get("id"), daily_call_limit=chosen.get("daily_call_limit"), daily_call_count=chosen.get("daily_call_count"))
        chosen["daily_call_count"] += 1
        chosen["last_used_at"] = _iso(now)
        chosen["updated_at"] = _iso(now)
        return chosen, keys, None

    # ---- Validate inputs (schema) ----
    try:
        if not isinstance(workspace_id, str):
            _log(None, "error", "VALIDATION_ERROR", "workspace_id must be a string")
            return _err("VALIDATION_ERROR", "workspace_id must be a string")
        # Be permissive: pattern exists in schema but audit shows callers may pass other gong_* ids in call_ids.
        if not re.match(r"^gong_ws_[0-9A-Z]{18,}$", workspace_id):
            _log(None, "error", "VALIDATION_ERROR", "workspace_id fails required pattern")
            return _err("VALIDATION_ERROR", "workspace_id fails required pattern")

        if not isinstance(call_ids, list) or len(call_ids) < 1:
            _log(None, "error", "VALIDATION_ERROR", "call_ids must be a non-empty array")
            return _err("VALIDATION_ERROR", "call_ids must be a non-empty array")

        # Do not strictly validate call_id pattern; accept any strings, and treat non-matching as simply not found.
        for cid in call_ids:
            if not isinstance(cid, str) or not cid.strip():
                _log(None, "error", "VALIDATION_ERROR", "call_ids must contain non-empty strings")
                return _err("VALIDATION_ERROR", "call_ids must contain non-empty strings")

        if include_sentences is None: include_sentences = False
        if include_topics is None: include_topics = False
        if include_speaker_index is None: include_speaker_index = False
        if not isinstance(include_sentences, bool) or not isinstance(include_topics, bool) or not isinstance(include_speaker_index, bool):
            _log(None, "error", "VALIDATION_ERROR", "include_sentences/include_topics/include_speaker_index must be boolean")
            return _err("VALIDATION_ERROR", "include_sentences/include_topics/include_speaker_index must be boolean")

        if sentences_limit is None:
            sentences_limit = 100
        if include_sentences:
            if not isinstance(sentences_limit, int) or sentences_limit < 1 or sentences_limit > 5000:
                _log(None, "error", "VALIDATION_ERROR", "sentences_limit must be an integer between 1 and 5000")
                return _err("VALIDATION_ERROR", "sentences_limit must be an integer between 1 and 5000")
            if sentences_cursor is not None and not isinstance(sentences_cursor, str):
                _log(None, "error", "VALIDATION_ERROR", "sentences_cursor must be a string")
                return _err("VALIDATION_ERROR", "sentences_cursor must be a string")
            if sentence_start_ms_gte is not None and (not isinstance(sentence_start_ms_gte, int) or sentence_start_ms_gte < 0):
                _log(None, "error", "VALIDATION_ERROR", "sentence_start_ms_gte must be an integer >= 0")
                return _err("VALIDATION_ERROR", "sentence_start_ms_gte must be an integer >= 0")
            if sentence_end_ms_lte is not None and (not isinstance(sentence_end_ms_lte, int) or sentence_end_ms_lte < 0):
                _log(None, "error", "VALIDATION_ERROR", "sentence_end_ms_lte must be an integer >= 0")
                return _err("VALIDATION_ERROR", "sentence_end_ms_lte must be an integer >= 0")
            if speaker_id is not None and (not isinstance(speaker_id, str) or not speaker_id.strip()):
                _log(None, "error", "VALIDATION_ERROR", "speaker_id must be a non-empty string")
                return _err("VALIDATION_ERROR", "speaker_id must be a non-empty string")
        else:
            # ignore sentence paging filters if not including sentences
            pass

        # ---- Resolve workspace + ambient auth key and enforce quota ----
        workspaces = _load("workspaces.json")
        if not isinstance(workspaces, list): workspaces = []
        ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id and w.get("status") != "deleted"), None)
        if ws is None:
            # reads return empty set? Here workspace_id is required and is tenancy scoping; missing workspace is NOT_FOUND.
            _log(None, "error", "NOT_FOUND", "Workspace not found")
            return _err("NOT_FOUND", "Workspace not found", workspace_id=workspace_id)

        api_key_row, keys_all, auth_err = _rate_and_select_key(workspace_id)
        if auth_err is not None:
            _log(None, "error", auth_err["error"]["code"], auth_err["error"]["message"], meta={"workspace_id": workspace_id})
            # persist any rollover changes if keys_all present
            if isinstance(keys_all, list):
                _save("api_keys.json", keys_all)
            return auth_err

        # ---- Fetch calls and transcripts ----
        calls = _load("calls.json")
        if not isinstance(calls, list): calls = []
        trxs = _load("call_transcripts.json")
        if not isinstance(trxs, list): trxs = []
        sentences_all = _load("transcript_sentences.json")
        if not isinstance(sentences_all, list): sentences_all = []

        # Build quick maps
        calls_by_id = {}
        for c in calls:
            if isinstance(c, dict) and c.get("id"):
                calls_by_id[c["id"]] = c

        trx_by_call_id = {}
        for t in trxs:
            if isinstance(t, dict) and t.get("call_id"):
                trx_by_call_id[t["call_id"]] = t

        results = []
        for cid in call_ids:
            c = calls_by_id.get(cid)
            # If ID doesn't exist or doesn't belong to workspace, return per-call error payload (not tool error)
            if not isinstance(c, dict) or c.get("workspace_id") != workspace_id:
                results.append({
                    "call_id": cid,
                    "ok": False,
                    "error": {"code": "NOT_FOUND", "message": "Call not found in workspace"},
                    "transcript": None
                })
                continue
            if c.get("status") == "deleted":
                results.append({
                    "call_id": cid,
                    "ok": False,
                    "error": {"code": "NOT_FOUND", "message": "Call is deleted"},
                    "transcript": None
                })
                continue
            if c.get("status") not in ("ready", "imported", "processing_transcript", "failed"):
                results.append({
                    "call_id": cid,
                    "ok": False,
                    "error": {"code": "INVALID_TRANSITION", "message": "Call status not eligible for transcript retrieval"},
                    "transcript": None
                })
                continue

            trx = trx_by_call_id.get(cid)
            if not isinstance(trx, dict) or trx.get("workspace_id") != workspace_id or trx.get("status") == "deleted":
                # Explicit per-call empty payload
                results.append({
                    "call_id": cid,
                    "ok": False,
                    "error": {"code": "NOT_FOUND", "message": "Transcript not found"},
                    "transcript": None
                })
                continue

            if trx.get("status") != "ready":
                # Must not return sentences when transcript not ready
                results.append({
                    "call_id": cid,
                    "ok": False,
                    "error": {"code": "INVALID_TRANSITION", "message": "Transcript not ready", "transcript_status": trx.get("status"), "error_message": trx.get("error_message")},
                    "transcript": {
                        "transcript_id": trx.get("id"),
                        "call_id": cid,
                        "workspace_id": workspace_id,
                        "status": trx.get("status"),
                        "language": trx.get("language"),
                        "topics": trx.get("topics") if include_topics else None,
                        "speaker_index": trx.get("speaker_index") if include_speaker_index else None,
                        "sentences": None,
                        "sentences_paging": None,
                    }
                })
                continue

            trx_payload = {
                "transcript_id": trx.get("id"),
                "call_id": cid,
                "workspace_id": workspace_id,
                "status": trx.get("status"),
                "language": trx.get("language"),
            }
            if include_topics:
                trx_payload["topics"] = trx.get("topics") if isinstance(trx.get("topics"), list) else []
            if include_speaker_index:
                trx_payload["speaker_index"] = trx.get("speaker_index") if isinstance(trx.get("speaker_index"), dict) else {}

            paging = None
            if include_sentences:
                tid = trx.get("id")
                # filter + sort
                filtered = []
                for s in sentences_all:
                    if not isinstance(s, dict):
                        continue
                    if s.get("transcript_id") != tid:
                        continue
                    if s.get("workspace_id") != workspace_id:
                        continue
                    # hide on deleted call/transcript already handled; rows kept but excluded by these conditions
                    if speaker_id is not None and s.get("speaker_id") != speaker_id:
                        continue
                    if sentence_start_ms_gte is not None:
                        v = s.get("start_ms")
                        if not isinstance(v, int) or v < sentence_start_ms_gte:
                            continue
                    if sentence_end_ms_lte is not None:
                        v = s.get("end_ms")
                        if not isinstance(v, int) or v > sentence_end_ms_lte:
                            continue
                    filtered.append(s)

                filtered.sort(key=lambda x: (x.get("ordinal") if isinstance(x.get("ordinal"), int) else 10**18, x.get("id") or ""))

                start_idx = 0
                if sentences_cursor:
                    # cursor is last seen sentence id (opaque): start after it if present
                    for i, s in enumerate(filtered):
                        if s.get("id") == sentences_cursor:
                            start_idx = i + 1
                            break

                page = filtered[start_idx:start_idx + sentences_limit]
                next_cursor = None
                has_more = start_idx + sentences_limit < len(filtered)
                if has_more and page:
                    next_cursor = page[-1].get("id")

                # Strip to sentence fields returned by API
                trx_payload["sentences"] = [{
                    "id": s.get("id"),
                    "speaker_id": s.get("speaker_id"),
                    "start_ms": s.get("start_ms"),
                    "end_ms": s.get("end_ms"),
                    "text": s.get("text"),
                    "ordinal": s.get("ordinal"),
                    "confidence": s.get("confidence"),
                } for s in page]
                paging = {
                    "limit": sentences_limit,
                    "cursor": sentences_cursor,
                    "next_cursor": next_cursor,
                    "has_more": bool(has_more),
                    "total_filtered": len(filtered),
                    "returned": len(page),
                }
                trx_payload["sentences_paging"] = paging

            results.append({
                "call_id": cid,
                "ok": True,
                "error": None,
                "transcript": trx_payload
            })

        # persist api key counter changes and log
        _save("api_keys.json", keys_all)
        _log(api_key_row.get("id"), "success", meta={"workspace_id": workspace_id, "call_count": len(call_ids)})

        return {
            "workspace_id": workspace_id,
            "results": results,
            "meta": {
                "requested_calls": len(call_ids),
                "returned_calls": len(results),
                "include_sentences": bool(include_sentences),
                "include_topics": bool(include_topics),
                "include_speaker_index": bool(include_speaker_index),
            }
        }
    except Exception as e:
        _log(None, "error", "VALIDATION_ERROR", "Unexpected error", meta={"detail": str(e)})
        return _err("VALIDATION_ERROR", "Unexpected error", detail=str(e))

