        _log(key_row.get("id"), "error", "NOT_FOUND", "Call not found", {"call_id": call_id})
        return _err("NOT_FOUND", "Call not found")

    out = dict(row)
    if not include_raw_metadata:
        out.pop("raw_metadata", None)

    _log(key_row.get("id"), "success", meta={"call_id": call_id, "workspace_id": ws.get("id")})
    return {"call": out}

