        })
        _save("request_logs.json", logs)

    def _gen_id(prefix):
        return prefix + base64.urlsafe_b64encode(os.urandom(14)).decode("ascii").rstrip("=").upper()

    # Validate
    if not isinstance(api_key, str) or not api_key.strip():
        _log(None, "error", "VALIDATION_ERROR", "api_key must be a non-empty string")
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if not isinstance(items, list) or len(items) < 1:
        _log(None, "error", "VALIDATION_ERROR", "items must be a non-empty array")
        return _err("VALIDATION_ERROR", "items must be a non-empty array")
    if len(items) > 500:
        _log(None, "error", "VALIDATION_ERROR", "items must have at most 500 elements")
        return _err("VALIDATION_ERROR", "items must have at most 500 elements")
    if idempotency_key is not None and (not isinstance(idempotency_key, str) or not idempotency_key.strip()):
        _log(None, "error", "VALIDATION_ERROR", "idempotency_key must be a non-empty string")
        return _err("VALIDATION_ERROR", "idempotency_key must be a non-empty string")

    keys = _load("api_keys.json")
    if not isinstance(keys, list): keys = []
    wss = _load("workspaces.json")
    if not isinstance(wss, list): wss = []

    # Authenticate by id; fallback if caller mistakenly passed workspace id
    key_row = next((k for k in keys if k.get("id") == api_key), None)
    if key_row is None:
        ws_guess = next((w for w in wss if w.get("id") == api_key), None)
        if ws_guess:
            key_row = next((k for k in keys if k.get("workspace_id") == ws_guess.get("id") and k.get("status") == "active"), None)
    if key_row is None or key_row.get("status") != "active":
