            if cnt + 1 > lim:
                _log(k.get("id"), "error", "QUOTA_EXCEEDED", "Daily call limit exceeded", {"daily_call_limit": lim, "daily_call_count": cnt})
                return _err("QUOTA_EXCEEDED", "Daily call limit exceeded", daily_call_limit=lim, daily_call_count=cnt)
            break
    if key_idx is None:
        _log(key_row.get("id"), "error", "UNAUTHORIZED", "Invalid API key")
        return _err("UNAUTHORIZED", "Invalid API key")

    calls = _load("calls.json")
    if not isinstance(calls, list): calls = []

    # Idempotency: treat as noop if exact same request already logged successfully with same idempotency_key
    if idempotency_key is not None:
        logs = _load("request_logs.json")
        if isinstance(logs, list):
            for r in reversed(logs):
                if isinstance(r, dict) and r.get("endpoint") == "import_calls" and r.get("status") == "success":
                    meta = r.get("meta") if isinstance(r.get("meta"), dict) else {}
                    if meta.get("idempotency_key") == idempotency_key and r.get("api_key_id") == key_row.get("id"):
                        # return previous result if available
                        prev = meta.get("result")
                        if isinstance(prev, dict):
                            _log(key_row.get("id"), "success", meta={"workspace_id": ws.get("id"), "idempotency_key": idempotency_key, "replayed": True, "result": prev})
                            # still count quota as a successful invocation
                            keys[key_idx]["daily_call_count"] = int(keys[key_idx].get("daily_call_count", 0)) + 1
                            keys[key_idx]["last_used_at"] = _iso(now)
                            keys[key_idx]["updated_at"] = _iso(now)
                            _save("api_keys.json", keys)
                            return prev

    # Validate each item and upsert
    allowed_item_status = {"imported", "processing_transcript", "ready", "failed"}
    results = []
    changed = False

    # index existing by (workspace_id, gong_call_id)
    existing_map = {}
    for c in calls:
        if c.get("workspace_id") == ws.get("id") and c.get("gong_call_id") is not None:
            existing_map[(ws.get("id"), str(c.get("gong_call_id")))] = c

    for idx, it in enumerate(items):
        if not isinstance(it, dict):
            _log(key_row.get("id"), "error", "VALIDATION_ERROR", f"items[{idx}] must be an object")
            return _err("VALIDATION_ERROR", f"items[{idx}] must be an object")

        gong_cid = it.get("gong_call_id")
