        if not isinstance(gong_cid, str) or not gong_cid.strip():
            _log(key_row.get("id"), "error", "VALIDATION_ERROR", f"items[{idx}].gong_call_id must be a non-empty string")
            return _err("VALIDATION_ERROR", f"items[{idx}].gong_call_id must be a non-empty string")
        if src != "gong":
            _log(key_row.get("id"), "error", "VALIDATION_ERROR", f"items[{idx}].source must be 'gong'")
            return _err("VALIDATION_ERROR", f"items[{idx}].source must be 'gong'")

        item_status = it.get("status")
        if item_status is not None and (not isinstance(item_status, str) or item_status not in allowed_item_status):
            _log(key_row.get("id"), "error", "VALIDATION_ERROR", f"items[{idx}].status is invalid")
            return _err("VALIDATION_ERROR", f"items[{idx}].status is invalid")

        started = it.get("started_at")
        ended = it.get("ended_at")
        started_dt = _parse_dt(started) if started is not None else None
        ended_dt = _parse_dt(ended) if ended is not None else None
        if started is not None and started_dt is None:
            _log(key_row.get("id"), "error", "VALIDATION_ERROR", f"items[{idx}].started_at must be RFC3339 date-time")
            return _err("VALIDATION_ERROR", f"items[{idx}].started_at must be RFC3339 date-time")
        if ended is not None and ended_dt is None:
            _log(key_row.get("id"), "error", "VALIDATION_ERROR", f"items[{idx}].ended_at must be RFC3339 date-time")
            return _err("VALIDATION_ERROR", f"items[{idx}].ended_at must be RFC3339 date-time")
        if started_dt is not None and ended_dt is not None and ended_dt < started_dt:
            _log(key_row.get("id"), "error", "VALIDATION_ERROR", f"items[{idx}] ended_at must be >= started_at")
            return _err("VALIDATION_ERROR", f"items[{idx}] ended_at must be >= started_at")

        dur = it.get("duration_seconds")
        if dur is not None:
            if not isinstance(dur, int) or dur < 0:
                _log(key_row.get("id"), "error", "VALIDATION_ERROR", f"items[{idx}].duration_seconds must be an integer >= 0")
                return _err("VALIDATION_ERROR", f"items[{idx}].duration_seconds must be an integer >= 0")

        participants = it.get("participants")
        if participants is not None and not isinstance(participants, list):
            _log(key_row.get("id"), "error", "VALIDATION_ERROR", f"items[{idx}].participants must be an array")
            return _err("VALIDATION_ERROR", f"items[{idx}].participants must be an array")
        if participants is None:
            participants = []

        raw = it.get("raw_metadata")
        if raw is not None and not isinstance(raw, dict):
            _log(key_row.get("id"), "error", "VALIDATION_ERROR", f"items[{idx}].raw_metadata must be an object")
            return _err("VALIDATION_ERROR", f"items[{idx}].raw_metadata must be an object")

        enqueue = it.get("enqueue_transcript_processing")
        if enqueue is not None and not isinstance(enqueue, bool):
            _log(key_row.get("id"), "error", "VALIDATION_ERROR", f"items[{idx}].enqueue_transcript_processing must be boolean")
            return _err("VALIDATION_ERROR", f"items[{idx}].enqueue_transcript_processing must be boolean")

        key = (ws.get("id"), str(gong_cid))
        existing = existing_map.get(key)

        if existing and existing.get("status") != "deleted":
            # update mutable fields (upsert)
            updated_fields = 0
            for field in ("title", "started_at", "ended_at", "duration_seconds", "participants", "raw_metadata"):
                if field in it:
                    existing[field] = it.get(field)
                    updated_fields += 1
            if enqueue is True:
                # move into processing_transcript if legal
                cur = existing.get("status")
                if cur in {"imported", "failed"}:
                    existing["status"] = "processing_transcript"
                    updated_fields += 1
                elif cur == "processing_transcript":
                    pass
                # if ready -> leave ready (no implicit downgrade)
            if item_status is not None and existing.get("status") != item_status:
                # transition validation
                transitions = {
                    "imported": {"processing_transcript", "ready", "failed", "deleted"},
                    "processing_transcript": {"ready", "failed", "deleted"},
                    "ready": {"deleted"},
                    "failed": {"processing_transcript", "deleted"},
                    "deleted": set(),
                }
                cur = existing.get("status")
                if item_status not in transitions.get(cur, set()):
                    _log(key_row.get("id"), "error", "INVALID_TRANSITION", f"Illegal call status transition {cur} -> {item_status}", {"call_id": existing.get("id")})
                    return _err("INVALID_TRANSITION", f"Illegal call status transition {cur} -> {item_status}")
                existing["status"] = item_status
                updated_fields += 1
            if updated_fields > 0:
                existing["updated_at"] = _iso(now)
                changed = True
                results.append({"gong_call_id": gong_cid, "call_id": existing.get("id"), "result": "updated"})
            else:
                results.append({"gong_call_id": gong_cid, "call_id": existing.get("id"), "result": "noop"})
        else:
            # create new call (cannot create deleted)
            initial_status = item_status or ("processing_transcript" if enqueue else "imported")
            if initial_status == "deleted":
                _log(key_row.get("id"), "error", "VALIDATION_ERROR", f"items[{idx}].status cannot be 'deleted' on create")
                return _err("VALIDATION_ERROR", f"items[{idx}].status cannot be 'deleted' on create")
            call_row = {
                "id": _gen_id("gong_call_"),
                "workspace_id": ws.get("id"),
                "gong_call_id": str(gong_cid),
                "title": it.get("title"),
                "started_at": it.get("started_at"),
                "ended_at": it.get("ended_at"),
                "duration_seconds": dur,
                "status": initial_status,
                "participants": participants if participants is not None else [],
                "source": "gong",
                "raw_metadata": raw,
                "created_at": _iso(now),
                "updated_at": _iso(now),
            }
            calls.append(call_row)
            existing_map[key] = call_row
            changed = True
            results.append({"gong_call_id": gong_cid, "call_id": call_row["id"], "result": "created"})

    if changed:
        _save("calls.json", calls)

    # consume quota and log success
    keys[key_idx]["daily_call_count"] = int(keys[key_idx].get("daily_call_count", 0)) + 1
    keys[key_idx]["last_used_at"] = _iso(now)
    keys[key_idx]["updated_at"] = _iso(now)
    _save("api_keys.json", keys)

    resp = {"workspace_id": ws.get("id"), "results": results}
    _log(key_row.get("id"), "success", meta={"workspace_id": ws.get("id"), "idempotency_key": idempotency_key, "result": resp})
    return resp

def update_call(api_key, call_id, title=None, started_at=None, ended_at=None, duration_seconds=None, participants=None, raw_metadata=None, status=None, **_extra):
    import json, os, datetime, time, re, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0437000" if __import__("os").path.isdir("./environment_mix/0437000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None, None
        if not isinstance(s, str) or not s.strip():
            return None, _err("VALIDATION_ERROR", "Invalid datetime; must be RFC3339 string")
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(ss)
        except ValueError:
            return None, _err("VALIDATION_ERROR", "Invalid datetime; must be RFC3339 string")
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc), None

    def _today0_utc(dt):
        d = dt.astimezone(datetime.timezone.utc).date()
        return datetime.datetime(d.year, d.month, d.day, 0, 0, 0, tzinfo=datetime.timezone.utc)

    def _gen_req_id():
        return "req_" + base64.urlsafe_b64encode(os.urandom(12)).decode("ascii").rstrip("=")

    def _log(api_key_id, status_s, error_code=None, error_message=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _gen_req_id(),
            "endpoint": "update_call",
            "api_key_id": api_key_id,
            "status": status_s,
            "error_code": error_code,
            "error_message": error_message,
            "meta": meta or {},
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _iso(now),
        })
        _save("request_logs.json", logs)

    def _auth_and_apply_quota(api_key_value, api_keys_rows):
        if not isinstance(api_key_value, str) or not api_key_value.strip():
            return None, _err("VALIDATION_ERROR", "api_key must be a non-empty string")
        key = None
        for k in api_keys_rows:
            if isinstance(k, dict) and k.get("status") == "active" and (k.get("id") == api_key_value):
                key = k
                break
        if key is None:
            for k in api_keys_rows:
                if isinstance(k, dict) and k.get("status") == "active" and (k.get("workspace_id") == api_key_value):
                    key = k
                    break
        if key is None:
            # cannot authenticate via key_hash; plaintext not stored
            return None, _err("UNAUTHORIZED", "Invalid API key")

        # daily rollover and quota enforcement
        today0 = _today0_utc(now)
        today0_iso = _iso(today0)
        if key.get("daily_count_date") != today0_iso:
            key["daily_call_count"] = 0
            key["daily_count_date"] = today0_iso

        limit = key.get("daily_call_limit")
        count = key.get("daily_call_count")
        if not isinstance(limit, int) or limit < 0:
            return None, _err("VALIDATION_ERROR", "API key daily_call_limit is invalid")
        if not isinstance(count, int) or count < 0:
            key["daily_call_count"] = 0
            count = 0

        if count + 1 > limit:
            return None, _err("QUOTA_EXCEEDED", "Daily call limit exceeded", daily_call_limit=limit, daily_call_count=count)

        # reserve quota for this successful invocation
        key["daily_call_count"] = count + 1
        key["last_used_at"] = _iso(now)
        key["updated_at"] = _iso(now)
        return key, None

    # --- Validate inputs early ---
    if not isinstance(call_id, str) or not re.match(r"^gong_call_[0-9A-Z]{18,}$", call_id):
        # still log with unknown key id when possible
        _log(None, "error", "VALIDATION_ERROR", "call_id must match ^gong_call_[0-9A-Z]{18,}$")
        return _err("VALIDATION_ERROR", "call_id must match ^gong_call_[0-9A-Z]{18,}$")

    if title is not None and (not isinstance(title, str)):
        _log(None, "error", "VALIDATION_ERROR", "title must be a string")
        return _err("VALIDATION_ERROR", "title must be a string")
    if duration_seconds is not None:
        if not isinstance(duration_seconds, int) or duration_seconds < 0:
            _log(None, "error", "VALIDATION_ERROR", "duration_seconds must be an integer >= 0")
            return _err("VALIDATION_ERROR", "duration_seconds must be an integer >= 0")
    if participants is not None:
        if not isinstance(participants, list):
            _log(None, "error", "VALIDATION_ERROR", "participants must be an array of objects")
            return _err("VALIDATION_ERROR", "participants must be an array of objects")
        for i, p in enumerate(participants):
            if not isinstance(p, dict):
                _log(None, "error", "VALIDATION_ERROR", f"participants[{i}] must be an object")
                return _err("VALIDATION_ERROR", f"participants[{i}] must be an object")
    if raw_metadata is not None and not isinstance(raw_metadata, dict):
        _log(None, "error", "VALIDATION_ERROR", "raw_metadata must be an object")
        return _err("VALIDATION_ERROR", "raw_metadata must be an object")
    allowed_status = {"imported", "processing_transcript", "ready", "failed", "deleted"}
    if status is not None and status not in allowed_status:
        _log(None, "error", "VALIDATION_ERROR", "Invalid status enum")
        return _err("VALIDATION_ERROR", "Invalid status enum")

    s_dt, err = _parse_dt(started_at)
    if err:
        _log(None, "error", err["error"]["code"], err["error"]["message"])
        return err
    e_dt, err = _parse_dt(ended_at)
    if err:
        _log(None, "error", err["error"]["code"], err["error"]["message"])
        return err
    if s_dt is not None and e_dt is not None and e_dt < s_dt:
        _log(None, "error", "VALIDATION_ERROR", "ended_at must be >= started_at")
        return _err("VALIDATION_ERROR", "ended_at must be >= started_at")

    # --- Load store ---
    api_keys_rows = _load("api_keys.json")
    if not isinstance(api_keys_rows, list):
        api_keys_rows = []
    calls_rows = _load("calls.json")
    if not isinstance(calls_rows, list):
        calls_rows = []
    workspaces_rows = _load("workspaces.json")
    if not isinstance(workspaces_rows, list):
        workspaces_rows = []
    transcripts_rows = _load("call_transcripts.json")
    if not isinstance(transcripts_rows, list):
        transcripts_rows = []

    # --- Authenticate + quota (only for successful calls) ---
    key, auth_err = _auth_and_apply_quota(api_key, api_keys_rows)
    if auth_err:
        _log(None, "error", auth_err["error"]["code"], auth_err["error"]["message"])
        return auth_err

    ws_id = key.get("workspace_id")
    ws = None
    for w in workspaces_rows:
        if isinstance(w, dict) and w.get("id") == ws_id:
            ws = w
            break
    if ws is None or ws.get("status") != "active":
        _log(key.get("id"), "error", "UNAUTHORIZED", "Workspace not active or not found")
        return _err("UNAUTHORIZED", "Workspace not active or not found")

    # --- Find call and enforce tenancy ---
    call = None
    call_idx = None
    for i, c in enumerate(calls_rows):
        if isinstance(c, dict) and c.get("id") == call_id:
            call = c
            call_idx = i
            break
    if call is None:
        _log(key.get("id"), "error", "NOT_FOUND", "Call not found")
        return _err("NOT_FOUND", "Call not found")
    if call.get("workspace_id") != ws_id:
        _log(key.get("id"), "error", "UNAUTHORIZED", "Call does not belong to authenticated workspace")
        return _err("UNAUTHORIZED", "Call does not belong to authenticated workspace")

    # --- Determine if anything changes; enforce transitions ---
    changes = {}
    if title is not None and title != call.get("title"):
        changes["title"] = title
    if started_at is not None:
        started_iso = _iso(s_dt)
        if started_iso != call.get("started_at"):
            changes["started_at"] = started_iso
    if ended_at is not None:
        ended_iso = _iso(e_dt)
        if ended_iso != call.get("ended_at"):
            changes["ended_at"] = ended_iso
    if duration_seconds is not None and duration_seconds != call.get("duration_seconds"):
        changes["duration_seconds"] = duration_seconds
    if participants is not None and participants != call.get("participants"):
        changes["participants"] = participants
    if raw_metadata is not None and raw_metadata != call.get("raw_metadata"):
        changes["raw_metadata"] = raw_metadata

    # status transition rules: must follow lifecycle transitions; but allow idempotent same-status update
    if status is not None:
        cur = call.get("status")
        if status != cur:
            transitions = {
                "imported": ["processing_transcript", "ready", "failed", "deleted"],
                "processing_transcript": ["ready", "failed", "deleted"],
                "ready": ["deleted"],
                "failed": ["processing_transcript", "deleted"],
                "deleted": [],
            }
            allowed_next = transitions.get(cur, [])
            if status not in allowed_next:
                _log(key.get("id"), "error", "INVALID_TRANSITION", f"Illegal call status transition {cur} -> {status}")
                return _err("INVALID_TRANSITION", f"Illegal call status transition {cur} -> {status}")
            changes["status"] = status

    if not changes:
        # idempotent success should still consume quota (already reserved) and be observable
        _save("api_keys.json", api_keys_rows)
        _log(key.get("id"), "success", meta={"call_id": call_id, "idempotent": True})
        return {
            "call": call,
            "updated_fields": [],
            "idempotent": True,
        }

    # Apply changes with constraints
    new_call = dict(call)
    new_call.update(changes)

    # constraint checks
    if new_call.get("participants") is None or not isinstance(new_call.get("participants"), list):
        _log(key.get("id"), "error", "VALIDATION_ERROR", "participants must be a non-null array")
        return _err("VALIDATION_ERROR", "participants must be a non-null array")
    if new_call.get("ended_at") is not None and new_call.get("started_at") is not None:
        s2, e2 = new_call.get("started_at"), new_call.get("ended_at")
        sd, _ = _parse_dt(s2)
        ed, _ = _parse_dt(e2)
        if sd and ed and ed < sd:
            _log(key.get("id"), "error", "VALIDATION_ERROR", "ended_at must be >= started_at")
            return _err("VALIDATION_ERROR", "ended_at must be >= started_at")
    if new_call.get("duration_seconds") is not None:
        if not isinstance(new_call.get("duration_seconds"), int) or new_call.get("duration_seconds") < 0:
            _log(key.get("id"), "error", "VALIDATION_ERROR", "duration_seconds must be >= 0")
            return _err("VALIDATION_ERROR", "duration_seconds must be >= 0")

    new_call["updated_at"] = _iso(now)

    # Persist call update
    calls_rows[call_idx] = new_call

    # Cascade soft delete
    cascaded = 0
    if changes.get("status") == "deleted":
        for tr in transcripts_rows:
            if isinstance(tr, dict) and tr.get("call_id") == call_id and tr.get("status") != "deleted":
                # enforce transcript lifecycle transitions
                cur_tr = tr.get("status")
                allowed_tr = {
                    "pending": ["ready", "error", "deleted"],
                    "ready": ["deleted"],
                    "error": ["pending", "deleted"],
                    "deleted": [],
                }.get(cur_tr, [])
                if "deleted" in allowed_tr:
                    tr["status"] = "deleted"
                    tr["updated_at"] = _iso(now)
                    cascaded += 1
                else:
                    # if transcript row has unknown status, still refuse illegal transition rather than partially delete
                    _log(key.get("id"), "error", "INVALID_TRANSITION", f"Illegal transcript status transition {cur_tr} -> deleted during call delete")
                    return _err("INVALID_TRANSITION", f"Illegal transcript status transition {cur_tr} -> deleted during call delete")

    # Save all mutated collections
    _save("calls.json", calls_rows)
    _save("call_transcripts.json", transcripts_rows)
    _save("api_keys.json", api_keys_rows)

    _log(key.get("id"), "success", meta={"call_id": call_id, "updated_fields": sorted(list(changes.keys())), "cascade_transcripts_deleted": cascaded})
    return {
        "call": new_call,
        "updated_fields": sorted(list(changes.keys())),
        "cascade": {"call_transcripts_deleted": cascaded} if changes.get("status") == "deleted" else {"call_transcripts_deleted": 0},
        "idempotent": False,
    }

def create_call_transcript(api_key, call_id, language=None, speaker_index=None, topics=None, status=None, error_message=None, **_extra):
    import json, os, datetime, time, re, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0437000" if __import__("os").path.isdir("./environment_mix/0437000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None or not isinstance(s, str):
            return None
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(ss)
        except ValueError:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _today0_utc(dt):
        d = dt.astimezone(datetime.timezone.utc).date()
        return datetime.datetime(d.year, d.month, d.day, 0, 0, 0, tzinfo=datetime.timezone.utc)

    def _log(api_key_id, status_s, error_code=None, error_message_s=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + base64.urlsafe_b64encode(os.urandom(12)).decode("ascii").rstrip("="),
            "endpoint": "create_call_transcript",
            "api_key_id": api_key_id,
            "status": status_s,
            "error_code": error_code,
            "error_message": error_message_s,
            "meta": meta or {},
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _iso(now),
        })
        _save("request_logs.json", logs)

    def _gen_id(prefix):
        return prefix + base64.urlsafe_b64encode(os.urandom(14)).decode("ascii").rstrip("=").upper()

    # Validate
    if not isinstance(api_key, str) or not api_key.strip():
        _log(None, "error", "VALIDATION_ERROR", "api_key must be a non-empty string")
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if not isinstance(call_id, str) or not re.match(r"^gong_call_[0-9A-Z]{18,}$", call_id):
        _log(None, "error", "VALIDATION_ERROR", "call_id is invalid")
        return _err("VALIDATION_ERROR", "call_id is invalid")
    if language is not None and not isinstance(language, str):
        _log(None, "error", "VALIDATION_ERROR", "language must be a string")
        return _err("VALIDATION_ERROR", "language must be a string")
    if speaker_index is not None and not isinstance(speaker_index, dict):
        _log(None, "error", "VALIDATION_ERROR", "speaker_index must be an object")
        return _err("VALIDATION_ERROR", "speaker_index must be an object")
    if topics is not None and not isinstance(topics, list):
        _log(None, "error", "VALIDATION_ERROR", "topics must be an array")
        return _err("VALIDATION_ERROR", "topics must be an array")
    if status is None:
        status = "pending"
    if status not in {"pending", "ready", "error"}:
        _log(None, "error", "VALIDATION_ERROR", "status is invalid")
        return _err("VALIDATION_ERROR", "status is invalid")
    if status == "error" and (error_message is None or not isinstance(error_message, str) or not error_message.strip()):
        _log(None, "error", "VALIDATION_ERROR", "error_message is required when status='error'")
        return _err("VALIDATION_ERROR", "error_message is required when status='error'")

    keys = _load("api_keys.json")
    if not isinstance(keys, list): keys = []
    wss = _load("workspaces.json")
    if not isinstance(wss, list): wss = []

    # Authenticate by id; fallback workspace-id-as-key
    key_row = next((k for k in keys if k.get("id") == api_key), None)
    if key_row is None:
        ws_guess = next((w for w in wss if w.get("id") == api_key), None)
        if ws_guess:
            key_row = next((k for k in keys if k.get("workspace_id") == ws_guess.get("id") and k.get("status") == "active"), None)
    if key_row is None or key_row.get("status") != "active":
        _log(key_row.get("id") if isinstance(key_row, dict) else None, "error", "UNAUTHORIZED", "Invalid API key")
        return _err("UNAUTHORIZED", "Invalid API key")

    ws = next((w for w in wss if w.get("id") == key_row.get("workspace_id")), None)
    if not ws or ws.get("status") != "active":
        _log(key_row.get("id"), "error", "UNAUTHORIZED", "Workspace is not active")
        return _err("UNAUTHORIZED", "Workspace is not active")

    # Quota before mutate; consume on success
    today0 = _today0_utc(now)
    key_idx = None
    for i, k in enumerate(keys):
        if k.get("id") == key_row.get("id"):
            key_idx = i
            dcd = _parse_dt(k.get("daily_count_date"))
            if dcd != today0:
                k["daily_call_count"] = 0
                k["daily_count_date"] = _iso(today0)
            try:
                cnt = int(k.get("daily_call_count", 0))
                lim = int(k.get("daily_call_limit", 0))
            except Exception:
                _log(k.get("id"), "error", "VALIDATION_ERROR", "API key quota fields are invalid")
                return _err("VALIDATION_ERROR", "API key quota fields are invalid")
            if cnt + 1 > lim:
                _log(k.get("id"), "error", "QUOTA_EXCEEDED", "Daily call limit exceeded", {"daily_call_limit": lim, "daily_call_count": cnt})
                return _err("QUOTA_EXCEEDED", "Daily call limit exceeded", daily_call_limit=lim, daily_call_count=cnt)
            break
    if key_idx is None:
        _log(key_row.get("id"), "error", "UNAUTHORIZED", "Invalid API key")
        return _err("UNAUTHORIZED", "Invalid API key")

    calls = _load("calls.json")
    if not isinstance(calls, list): calls = []
    call_row = next((c for c in calls if c.get("id") == call_id), None)
    if not call_row:
        _log(key_row.get("id"), "error", "NOT_FOUND", "Call not found", {"call_id": call_id})
        return _err("NOT_FOUND", "Call not found")
    if call_row.get("workspace_id") != ws.get("id"):
        _log(key_row.get("id"), "error", "UNAUTHORIZED", "Call belongs to a different workspace", {"call_id": call_id})
        return _err("UNAUTHORIZED", "Call belongs to a different workspace")
    if call_row.get("status") == "deleted":
        _log(key_row.get("id"), "error", "INVALID_TRANSITION", "Cannot create transcript for a deleted call", {"call_id": call_id})
        return _err("INVALID_TRANSITION", "Cannot create transcript for a deleted call")

    transcripts = _load("call_transcripts.json")
    if not isinstance(transcripts, list): transcripts = []

    existing = next((t for t in transcripts if t.get("call_id") == call_id), None)
    if existing:
        # Replace only if not deleted (idempotent-ish: overwrite fields and bump updated_at)
        if existing.get("status") == "deleted":
            _log(key_row.get("id"), "error", "INVALID_TRANSITION", "Cannot replace a deleted transcript", {"call_id": call_id, "transcript_id": existing.get("id")})
            return _err("INVALID_TRANSITION", "Cannot replace a deleted transcript")
        existing["workspace_id"] = call_row.get("workspace_id")  # enforce inheritance
        existing["language"] = language
        existing["speaker_index"] = speaker_index if speaker_index is not None else {}
        existing["topics"] = topics if topics is not None else []
        existing["status"] = status
        existing["error_message"] = error_message if status == "error" else None
        existing["updated_at"] = _iso(now)
        _save("call_transcripts.json", transcripts)

        keys[key_idx]["daily_call_count"] = int(keys[key_idx].get("daily_call_count", 0)) + 1
        keys[key_idx]["last_used_at"] = _iso(now)
        keys[key_idx]["updated_at"] = _iso(now)
        _save("api_keys.json", keys)

        _log(key_row.get("id"), "success", meta={"workspace_id": ws.get("id"), "call_id": call_id, "transcript_id": existing.get("id"), "result": "updated"})
        return {"transcript": existing}

    # Create new transcript
    trx_row = {
        "id": _gen_id("gong_trx_"),  # datastore uses gong_trx_ prefix
        "call_id": call_id,
        "workspace_id": call_row.get("workspace_id"),
        "language": language,
        "speaker_index": speaker_index if speaker_index is not None else {},
        "topics": topics if topics is not None else [],
        "status": status,
        "error_message": error_message if status == "error" else None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    transcripts.append(trx_row)
    _save("call_transcripts.json", transcripts)

    keys[key_idx]["daily_call_count"] = int(keys[key_idx].get("daily_call_count", 0)) + 1
    keys[key_idx]["last_used_at"] = _iso(now)
    keys[key_idx]["updated_at"] = _iso(now)
    _save("api_keys.json", keys)

    _log(key_row.get("id"), "success", meta={"workspace_id": ws.get("id"), "call_id": call_id, "transcript_id": trx_row.get("id"), "result": "created"})
    return {"transcript": trx_row}

def add_transcript_sentences(api_key, transcript_id, sentences, mode=None, **_extra):
    import json, os, datetime, time, re, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0437000" if __import__("os").path.isdir("./environment_mix/0437000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _today0_utc(dt):
        d = dt.astimezone(datetime.timezone.utc).date()
        return datetime.datetime(d.year, d.month, d.day, 0, 0, 0, tzinfo=datetime.timezone.utc)

    def _gen_req_id():
        return "req_" + base64.urlsafe_b64encode(os.urandom(12)).decode("ascii").rstrip("=")

    def _gen_id(prefix):
        return prefix + base64.urlsafe_b64encode(os.urandom(14)).decode("ascii").rstrip("=").upper()

    def _log(api_key_id, status_s, error_code=None, error_message=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _gen_req_id(),
            "endpoint": "add_transcript_sentences",
            "api_key_id": api_key_id,
            "status": status_s,
            "error_code": error_code,
            "error_message": error_message,
            "meta": meta or {},
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _iso(now),
        })
        _save("request_logs.json", logs)

    def _auth_and_apply_quota(api_key_value, api_keys_rows):
        if not isinstance(api_key_value, str) or not api_key_value.strip():
            return None, _err("VALIDATION_ERROR", "api_key must be a non-empty string")
        key = None
        for k in api_keys_rows:
            if isinstance(k, dict) and k.get("status") == "active" and (k.get("id") == api_key_value):
                key = k
                break
        if key is None:
            for k in api_keys_rows:
                if isinstance(k, dict) and k.get("status") == "active" and (k.get("workspace_id") == api_key_value):
                    key = k
                    break
        if key is None:
            return None, _err("UNAUTHORIZED", "Invalid API key")

        today0 = _today0_utc(now)
        today0_iso = _iso(today0)
        if key.get("daily_count_date") != today0_iso:
            key["daily_call_count"] = 0
            key["daily_count_date"] = today0_iso

        limit = key.get("daily_call_limit")
        count = key.get("daily_call_count")
        if not isinstance(limit, int) or limit < 0:
            return None, _err("VALIDATION_ERROR", "API key daily_call_limit is invalid")
        if not isinstance(count, int) or count < 0:
            key["daily_call_count"] = 0
            count = 0

        if count + 1 > limit:
            return None, _err("QUOTA_EXCEEDED", "Daily call limit exceeded", daily_call_limit=limit, daily_call_count=count)

        key["daily_call_count"] = count + 1
        key["last_used_at"] = _iso(now)
        key["updated_at"] = _iso(now)
        return key, None

    # --- Validate inputs ---
    if mode is None:
        mode = "insert"
    if mode not in ("insert", "upsert"):
        _log(None, "error", "VALIDATION_ERROR", "mode must be 'insert' or 'upsert'")
        return _err("VALIDATION_ERROR", "mode must be 'insert' or 'upsert'")

    # Tool schema pattern says gong_trn_..., but datastore uses gong_trx_...; accept both.
    if not isinstance(transcript_id, str) or not transcript_id.strip() or not re.match(r"^gong_tr[ xn]_[0-9A-Z]{18,}$".replace(" ", ""), transcript_id):
        # the regex above is a trick; simpler explicit check:
        if not (isinstance(transcript_id, str) and (re.match(r"^gong_trn_[0-9A-Z]{18,}$", transcript_id) or re.match(r"^gong_trx_[0-9A-Z]{18,}$", transcript_id))):
            _log(None, "error", "VALIDATION_ERROR", "transcript_id must match ^gong_trn_... or ^gong_trx_...")
            return _err("VALIDATION_ERROR", "transcript_id must match ^gong_trn_... or ^gong_trx_...")

    if not isinstance(sentences, list) or len(sentences) < 1:
        _log(None, "error", "VALIDATION_ERROR", "sentences must be a non-empty array")
        return _err("VALIDATION_ERROR", "sentences must be a non-empty array")
    if len(sentences) > 10000:
        _log(None, "error", "VALIDATION_ERROR", "sentences must have at most 10000 items")
        return _err("VALIDATION_ERROR", "sentences must have at most 10000 items")

    for i, s in enumerate(sentences):
        if not isinstance(s, dict):
            _log(None, "error", "VALIDATION_ERROR", f"sentences[{i}] must be an object")
            return _err("VALIDATION_ERROR", f"sentences[{i}] must be an object")
        for req in ("speaker_id", "start_ms", "end_ms", "text", "ordinal"):
            if req not in s:
                _log(None, "error", "VALIDATION_ERROR", f"sentences[{i}].{req} is required")
                return _err("VALIDATION_ERROR", f"sentences[{i}].{req} is required")
        if not isinstance(s["speaker_id"], str) or not s["speaker_id"].strip():
            _log(None, "error", "VALIDATION_ERROR", f"sentences[{i}].speaker_id must be a non-empty string")
            return _err("VALIDATION_ERROR", f"sentences[{i}].speaker_id must be a non-empty string")
        if not isinstance(s["start_ms"], int) or s["start_ms"] < 0:
            _log(None, "error", "VALIDATION_ERROR", f"sentences[{i}].start_ms must be integer >= 0")
            return _err("VALIDATION_ERROR", f"sentences[{i}].start_ms must be integer >= 0")
        if not isinstance(s["end_ms"], int) or s["end_ms"] < 0:
            _log(None, "error", "VALIDATION_ERROR", f"sentences[{i}].end_ms must be integer >= 0")
            return _err("VALIDATION_ERROR", f"sentences[{i}].end_ms must be integer >= 0")
        if s["end_ms"] < s["start_ms"]:
            _log(None, "error", "VALIDATION_ERROR", f"sentences[{i}].end_ms must be >= start_ms")
            return _err("VALIDATION_ERROR", f"sentences[{i}].end_ms must be >= start_ms")
        if not isinstance(s["text"], str) or not s["text"]:
            _log(None, "error", "VALIDATION_ERROR", f"sentences[{i}].text must be a non-empty string")
            return _err("VALIDATION_ERROR", f"sentences[{i}].text must be a non-empty string")
        if not isinstance(s["ordinal"], int) or s["ordinal"] < 0:
            _log(None, "error", "VALIDATION_ERROR", f"sentences[{i}].ordinal must be integer >= 0")
            return _err("VALIDATION_ERROR", f"sentences[{i}].ordinal must be integer >= 0")
        if "confidence" in s and s["confidence"] is not None:
            if not isinstance(s["confidence"], (int, float)) or s["confidence"] < 0 or s["confidence"] > 1:
                _log(None, "error", "VALIDATION_ERROR", f"sentences[{i}].confidence must be between 0 and 1")
                return _err("VALIDATION_ERROR", f"sentences[{i}].confidence must be between 0 and 1")
        extra_keys = set(s.keys()) - {"speaker_id", "start_ms", "end_ms", "text", "ordinal", "confidence"}
        if extra_keys:
            _log(None, "error", "VALIDATION_ERROR", f"sentences[{i}] has unknown fields: {sorted(list(extra_keys))}")
            return _err("VALIDATION_ERROR", f"sentences[{i}] has unknown fields: {sorted(list(extra_keys))}")

    # Reject duplicate ordinals within request payload (contiguous not required; duplicates forbidden)
    ords = [s["ordinal"] for s in sentences]
    if len(set(ords)) != len(ords):
        _log(None, "error", "CONFLICT", "Duplicate ordinal values in request payload are not allowed")
        return _err("CONFLICT", "Duplicate ordinal values in request payload are not allowed")

    # --- Load store ---
    api_keys_rows = _load("api_keys.json")
    if not isinstance(api_keys_rows, list):
        api_keys_rows = []
    workspaces_rows = _load("workspaces.json")
    if not isinstance(workspaces_rows, list):
        workspaces_rows = []
    transcripts_rows = _load("call_transcripts.json")
    if not isinstance(transcripts_rows, list):
        transcripts_rows = []
    calls_rows = _load("calls.json")
    if not isinstance(calls_rows, list):
        calls_rows = []
    sentences_rows = _load("transcript_sentences.json")
    if not isinstance(sentences_rows, list):
        sentences_rows = []

    # --- Authenticate + quota (only for success) ---
    key, auth_err = _auth_and_apply_quota(api_key, api_keys_rows)
    if auth_err:
        _log(None, "error", auth_err["error"]["code"], auth_err["error"]["message"])
        return auth_err

    ws_id = key.get("workspace_id")
    ws = None
    for w in workspaces_rows:
        if isinstance(w, dict) and w.get("id") == ws_id:
            ws = w
            break
    if ws is None or ws.get("status") != "active":
        _log(key.get("id"), "error", "UNAUTHORIZED", "Workspace not active or not found")
        return _err("UNAUTHORIZED", "Workspace not active or not found")

    tr = None
    for r in transcripts_rows:
        if isinstance(r, dict) and r.get("id") == transcript_id:
            tr = r
            break
    if tr is None:
        _log(key.get("id"), "error", "NOT_FOUND", "Transcript not found")
        return _err("NOT_FOUND", "Transcript not found")

    if tr.get("workspace_id") != ws_id:
        _log(key.get("id"), "error", "UNAUTHORIZED", "Transcript does not belong to authenticated workspace")
        return _err("UNAUTHORIZED", "Transcript does not belong to authenticated workspace")

    if tr.get("status") == "deleted":
        _log(key.get("id"), "error", "INVALID_TRANSITION", "Cannot add sentences to a deleted transcript")
        return _err("INVALID_TRANSITION", "Cannot add sentences to a deleted transcript")

    call_id = tr.get("call_id")
    if not isinstance(call_id, str) or not call_id:
        _log(key.get("id"), "error", "VALIDATION_ERROR", "Transcript call_id is invalid")
        return _err("VALIDATION_ERROR", "Transcript call_id is invalid")

    parent_call = None
    for c in calls_rows:
        if isinstance(c, dict) and c.get("id") == call_id:
            parent_call = c
            break
    if parent_call is None:
        _log(key.get("id"), "error", "NOT_FOUND", "Parent call not found for transcript")
        return _err("NOT_FOUND", "Parent call not found for transcript")
    if parent_call.get("workspace_id") != ws_id:
        _log(key.get("id"), "error", "UNAUTHORIZED", "Parent call does not belong to authenticated workspace")
        return _err("UNAUTHORIZED", "Parent call does not belong to authenticated workspace")
    if parent_call.get("status") == "deleted":
        _log(key.get("id"), "error", "INVALID_TRANSITION", "Cannot add sentences to a transcript whose call is deleted")
        return _err("INVALID_TRANSITION", "Cannot add sentences to a transcript whose call is deleted")

    speaker_index = tr.get("speaker_index")
    if not isinstance(speaker_index, dict):
        _log(key.get("id"), "error", "VALIDATION_ERROR", "Transcript speaker_index is missing or invalid")
        return _err("VALIDATION_ERROR", "Transcript speaker_index is missing or invalid")

    # Enforce speaker_id existence
    for i, s in enumerate(sentences):
        if s["speaker_id"] not in speaker_index:
            _log(key.get("id"), "error", "VALIDATION_ERROR", f"sentences[{i}].speaker_id '{s['speaker_id']}' not found in transcript speaker_index")
            return _err("VALIDATION_ERROR", f"sentences[{i}].speaker_id '{s['speaker_id']}' not found in transcript speaker_index")

    # Existing rows for transcript
    existing_by_ordinal = {}
    for row in sentences_rows:
        if isinstance(row, dict) and row.get("transcript_id") == transcript_id:
            o = row.get("ordinal")
            if isinstance(o, int):
                existing_by_ordinal[o] = row

    inserted = 0
    updated = 0
    touched_ids = []

    # Insert/upsert
    for s in sentences:
        o = s["ordinal"]
        existing = existing_by_ordinal.get(o)
        if existing is not None and mode == "insert":
            _log(key.get("id"), "error", "CONFLICT", f"Ordinal {o} already exists for transcript")
            return _err("CONFLICT", f"Ordinal {o} already exists for transcript")
        if existing is None:
            new_row = {
                "id": _gen_id("gong_snt_"),
                "transcript_id": transcript_id,
                "call_id": call_id,
                "workspace_id": ws_id,
                "speaker_id": s["speaker_id"],
                "start_ms": s["start_ms"],
                "end_ms": s["end_ms"],
                "text": s["text"],
                "ordinal": o,
                "confidence": s.get("confidence", None),
                "created_at": _iso(now),
                "updated_at": _iso(now),
            }
            sentences_rows.append(new_row)
            existing_by_ordinal[o] = new_row
            inserted += 1
            touched_ids.append(new_row["id"])
        else:
            # upsert: replace mutable fields, keep id/created_at
            existing["speaker_id"] = s["speaker_id"]
            existing["start_ms"] = s["start_ms"]
            existing["end_ms"] = s["end_ms"]
            existing["text"] = s["text"]
            existing["confidence"] = s.get("confidence", None)
            existing["call_id"] = call_id
            existing["workspace_id"] = ws_id
            existing["updated_at"] = _iso(now)
            updated += 1
            touched_ids.append(existing.get("id"))

    if inserted == 0 and updated == 0:
        _log(key.get("id"), "error", "NOT_FOUND", "No rows were inserted or updated")
        return _err("NOT_FOUND", "No rows were inserted or updated")

    # Persist
    _save("transcript_sentences.json", sentences_rows)
    _save("api_keys.json", api_keys_rows)

    _log(key.get("id"), "success", meta={"transcript_id": transcript_id, "mode": mode, "inserted": inserted, "updated": updated})
    return {
        "transcript_id": transcript_id,
        "call_id": call_id,
        "workspace_id": ws_id,
        "mode": mode,
        "inserted": inserted,
        "updated": updated,
        "sentence_ids": [i for i in touched_ids if isinstance(i, str)],
    }
